// O(n²) — 목록 안에서 또 목록을 돈다
const dup1 = list.filter((x, i) => list.indexOf(x) !== i);

// O(n) — 한 번 훑으며 본 것을 기억한다
const seen = new Set(), dup2 = [];
for (const x of list) { if (seen.has(x)) dup2.push(x); else seen.add(x); }

// 느림: 주문마다 사용자 목록을 뒤진다 (O(주문 × 사용자))
orders.map((o) => users.find((u) => u.id === o.userId));

// 빠름: 색인을 한 번 만든다 (O(사용자 + 주문))
const byId = new Map(users.map((u) => [u.id, u]));
orders.map((o) => byId.get(o.userId));

const memo = new Map();
function fib(n) {
  if (n < 2) return n;
  if (memo.has(n)) return memo.get(n);
  const v = fib(n - 1) + fib(n - 2);
  memo.set(n, v);
  return v;
}
